target.css:
:root {
  --card: #fffaf0;
  --ink: #26352e;
  --tomato: #c94e3b;
  --sage: #dce8d6;
  --line: #26352e;
}

.soup-card {
  width: 440px;
  padding: 18px;
  border: 2px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bowl {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 14px;
  background: var(--tomato);
  font-size: 25px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--tomato);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1;
}

.details {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--sage);
  font-size: 14px;
}

.details p {
  margin: 0;
}

.badge {
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
}

footer {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
  font-size: 13px;
  font-weight: 700;
}
